<script setup lang="ts">import{Head,router}from'@inertiajs/vue3';import{ref}from'vue';import AppLayout from'../../../layouts/AppLayout.vue';interface C{id:number;name:string;grade_level:number}interface R{nis:string;name:string;present:number;sick:number;permitted:number;absent:number;total:number;attendance_rate:number}const p=defineProps<{classes:C[];selected_class_id:string;from:string;to:string;rows:R[]}>();const c=ref(p.selected_class_id),f=ref(p.from),t=ref(p.to);const apply=()=>router.get('/akademik/presensi/rekap',{class_group_id:c.value,from:f.value,to:t.value},{preserveState:true});const exportUrl=()=>`/akademik/presensi/rekap/export?class_group_id=${c.value}&from=${f.value}&to=${t.value}`;</script>
<template><AppLayout title="Rekap Absensi"><Head title="Rekap Absensi"/><main class="view space-y-6"><section class="hero-card recap-hero"><div><p class="eyebrow">Analitik kehadiran</p><h1>Rekap absensi siswa</h1><p>Tinjau kehadiran per rombel dan rentang tanggal, lalu unduh data spreadsheet.</p></div><a class="primary-button" :href="exportUrl()">Unduh CSV</a></section><section class="panel filter"><label>Rombel<select v-model="c"><option v-for="x in classes" :key="x.id" :value="String(x.id)">{{x.name}}</option></select></label><label>Dari<input v-model="f" type="date"/></label><label>Sampai<input v-model="t" type="date"/></label><button class="secondary-button" @click="apply">Terapkan</button></section><section class="panel table-scroll"><table class="recap-table"><thead><tr><th>NIS</th><th>Nama</th><th>Hadir</th><th>Sakit</th><th>Izin</th><th>Alpa</th><th>Total</th><th>Kehadiran</th></tr></thead><tbody><tr v-for="r in rows" :key="r.nis"><td>{{r.nis}}</td><td><strong>{{r.name}}</strong></td><td>{{r.present}}</td><td>{{r.sick}}</td><td>{{r.permitted}}</td><td>{{r.absent}}</td><td>{{r.total}}</td><td><span class="rate">{{r.attendance_rate}}%</span></td></tr><tr v-if="!rows.length"><td colspan="8" class="empty">Belum ada data pada rentang ini.</td></tr></tbody></table></section></main></AppLayout></template>
<style scoped>.recap-hero,.filter{display:flex;align-items:center;justify-content:space-between;gap:1rem}.filter{padding:1rem;justify-content:flex-start}.filter label{display:grid;gap:.3rem;color:#475569;font-size:.75rem;font-weight:700}.filter input,.filter select{padding:.55rem .7rem;border:1px solid #cbd5e1;border-radius:.6rem}.recap-table{width:100%;border-collapse:collapse}.recap-table th,.recap-table td{padding:.8rem 1rem;border-bottom:1px solid #e2e8f0;text-align:left;font-size:.8rem}.recap-table th{background:#f8fafc;color:#64748b;text-transform:uppercase}.rate{padding:.25rem .5rem;border-radius:999px;background:#eef2ff;color:#4338ca;font-weight:800}.empty{text-align:center!important;color:#94a3b8}@media(max-width:760px){.recap-hero,.filter{align-items:stretch;flex-direction:column}}</style>
